use crate::init::uniform;
use crate::qat::Bits;
use ndarray::{Array1, Array2};

#[derive(Clone,Debug)]pub struct RwkvCmix{pub channels:usize,pub layer_id:usize,pub n_layer:usize,pub x_k:Array1<f32>,pub key:Array2<f32>,pub value:Array2<f32>,pub qat_3bit:bool,pub qat_bits:u8}
impl RwkvCmix{pub fn new(channels:usize,layer_id:usize,n_layer:usize)->Self{Self::new_seeded(channels,layer_id,n_layer,0x434d_4958_4b4559)}pub fn new_seeded(channels:usize,layer_id:usize,n_layer:usize,seed:u64)->Self{assert!(channels>0&&n_layer>0&&layer_id<n_layer);let r=1.0-layer_id as f32/n_layer as f32;let x_k=Array1::from_iter((0..channels).map(|i|{let d=i as f32/channels as f32;1.0-d.powf(r.powi(4))}));let hidden=channels*4;let scale=0.5/(channels as f32).sqrt();Self{channels,layer_id,n_layer,x_k,key:uniform(channels,hidden,-scale,scale,seed^layer_id as u64),value:Array2::zeros((hidden,channels)),qat_3bit:false,qat_bits:0}}pub fn from_weights(x_k:Array1<f32>,key:Array2<f32>,value:Array2<f32>,layer_id:usize,n_layer:usize)->Self{let channels=x_k.len();assert_eq!(key.dim(),(channels,value.nrows()));assert_eq!(value.ncols(),channels);Self{channels,layer_id,n_layer,x_k,key,value,qat_3bit:false,qat_bits:0}}pub fn with_qat_3bit(self,on:bool)->Self{self.with_qat_bits(if on{3}else{0})}pub fn with_qat_bits(mut self,bits:u8)->Self{assert!(matches!(bits,0|2|3|4|8));self.qat_bits=bits;self.qat_3bit=bits==3;self}pub(crate)fn effective_weights(&self)->(Array2<f32>,Array2<f32>){match Bits::from_bits(self.qat_bits){Err(_)=>(self.key.clone(),self.value.clone()),Ok(b)=>{let k=crate::qat::fake_quantize(&self.key.t().to_owned(),b).t().to_owned();let v=crate::qat::fake_quantize(&self.value.t().to_owned(),b).t().to_owned();(k,v)}}}fn mixed(&self,x:&Array2<f32>,prev:Option<&Array1<f32>>)->Array2<f32>{let mut m=x.clone();for t in 0..x.nrows(){for c in 0..self.channels{let p=if t==0{prev.map_or(0.0,|v|v[c])}else{x[[t-1,c]]};m[[t,c]]=x[[t,c]]+(p-x[[t,c]])*self.x_k[c]}}m}fn relu_squared(v:f32)->f32{let v=v.max(0.0);v*v}fn linear(&self,input:&Array2<f32>,weight:&Array2<f32>)->Array2<f32>{match Bits::from_bits(self.qat_bits){Ok(bits)=>{let(w,s)=crate::qat::quantize_weight(&weight.t().to_owned(),bits);let input=input.as_standard_layout();let values=crate::gpu::packed_linear(input.as_slice().expect("standard layout input"),&w,&s,input.nrows(),weight.ncols(),weight.nrows(),bits.bits()).unwrap();Array2::from_shape_vec((input.nrows(),weight.ncols()),values).unwrap()},Err(_)=>input.dot(weight)}}pub fn forward(&self,x:&Array2<f32>,prev:Option<&Array1<f32>>)->(Array2<f32>,Array1<f32>){let m=self.mixed(x,prev);let mut h=self.linear(&m,&self.key);h.mapv_inplace(Self::relu_squared);(self.linear(&h,&self.value),x.row(x.nrows()-1).to_owned())}pub fn forward_selected(&self,x:&Array2<f32>,prev:Option<&Array1<f32>>)->Array2<f32>{let m=self.mixed(x,prev);let mut h=self.linear(&m,&self.key);h.mapv_inplace(Self::relu_squared);self.linear(&h,&self.value)}pub fn forward_rows(&self,x:&Array2<f32>,prev:Option<&Array1<f32>>,rows:&[usize])->Array2<f32>{let mut m=Array2::zeros((rows.len(),self.channels));for(o,&t)in rows.iter().enumerate(){for c in 0..self.channels{let p=if t==0{prev.map_or(0.0,|v|v[c])}else{x[[t-1,c]]};m[[o,c]]=x[[t,c]]+(p-x[[t,c]])*self.x_k[c]}}let mut h=self.linear(&m,&self.key);h.mapv_inplace(Self::relu_squared);self.linear(&h,&self.value)}pub fn parameter_count(&self)->usize{self.x_k.len()+self.key.len()+self.value.len()}}
#[cfg(test)]mod tests_rwkv_cmix{use super::*;#[test]fn bit_widths_execute(){let x=Array2::ones((2,8));for b in[2u8,3,4,8]{let l=RwkvCmix::new(8,0,4).with_qat_bits(b);let(y,_)=l.forward(&x,None);assert!(y.iter().all(|v|v.is_finite()));}}#[test]fn packed_path_matches_shape(){let x=Array2::ones((3,8));let l=RwkvCmix::new(8,0,4).with_qat_bits(4);let(y,_)=l.forward(&x,None);assert_eq!(y.dim(),(3,8));}}


// ===== rwkv_cmix_backward =====

pub struct CmixBackward{pub grad_input:Array2<f32>,pub grad_prev:Array1<f32>,pub grad_x_k:Array1<f32>,pub grad_key:Array2<f32>,pub grad_value:Array2<f32>}

pub fn backward(input:&Array2<f32>,prev:Option<&Array1<f32>>,grad_output:&Array2<f32>,x_k:&Array1<f32>,key_weight:&Array2<f32>,value_weight:&Array2<f32>)->CmixBackward{
 let(steps,channels)=input.dim();assert!(steps>0);assert_eq!(x_k.len(),channels);assert_eq!(key_weight.nrows(),channels);assert_eq!(value_weight.ncols(),channels);assert_eq!(grad_output.dim(),(steps,channels));
 let mut mixed=input.clone();for t in 0..steps{for c in 0..channels{let p=if t==0{prev.map_or(0.0,|v|v[c])}else{input[[t-1,c]]};mixed[[t,c]]=input[[t,c]]+(p-input[[t,c]])*x_k[c];}}
 let pre=mixed.dot(key_weight);let hidden=pre.mapv(|v|v.max(0.0).powi(2));let grad_hidden=grad_output.dot(&value_weight.t());let mut grad_pre=Array2::zeros(pre.raw_dim());for((dst,&p),&g)in grad_pre.iter_mut().zip(pre.iter()).zip(grad_hidden.iter()){*dst=if p>0.0{2.0*p*g}else{0.0};}
 let grad_key=mixed.t().dot(&grad_pre);let grad_value=hidden.t().dot(grad_output);let grad_mixed=grad_pre.dot(&key_weight.t());let mut grad_input=Array2::zeros(input.raw_dim());let mut grad_prev=Array1::zeros(channels);let mut grad_x_k=Array1::zeros(channels);
 for t in 0..steps{for c in 0..channels{let p=if t==0{prev.map_or(0.0,|v|v[c])}else{input[[t-1,c]]};let gm=grad_mixed[[t,c]];grad_input[[t,c]]+=gm*(1.0-x_k[c]);grad_x_k[c]+=gm*(p-input[[t,c]]);if t==0{if prev.is_some(){grad_prev[c]+=gm*x_k[c];}}else{grad_input[[t-1,c]]+=gm*x_k[c];}}}
 CmixBackward{grad_input,grad_prev,grad_x_k,grad_key,grad_value}
}

#[cfg(test)]mod tests_rwkv_cmix_backward{use super::*;use ndarray::{Array1,Array2};#[test]fn backward_shapes(){let x=Array2::ones((3,4));let prev=Array1::zeros(4);let key=Array2::ones((4,16));let value=Array2::ones((16,4));let g=backward(&x,Some(&prev),&Array2::ones((3,4)),&Array1::ones(4),&key,&value);assert_eq!(g.grad_input.dim(),(3,4));assert_eq!(g.grad_key.dim(),(4,16));assert_eq!(g.grad_value.dim(),(16,4));}}
